"""Embedding models for tensor::infer and `query nearest` (ADR-010).

Every model declares `id` and `dimension` and implements `embed(texts)`,
returning one L2-normalized vector of exactly `dimension` floats per text.
The compiler picks the model and checks that the program's
`vector_embedding` field has the same dimension; this module checks it again
at run time.
"""
import json
import os
import urllib.error
import urllib.request

TENSOR_MAX_TOKENS = 256
HTTP_TIMEOUT_SECONDS = 60


def _normalize(vector, dimension, model_id):
    values = [float(v) for v in vector]
    if len(values) != dimension:
        raise RuntimeError(
            f"embedding model `{model_id}` returned {len(values)} floats, expected {dimension}"
        )
    norm = sum(v * v for v in values) ** 0.5
    if not norm or norm != norm or norm == float("inf"):
        raise RuntimeError(f"embedding model `{model_id}` produced a non-normalizable vector")
    return [v / norm for v in values]


class EmbeddingModel:
    """A text embedding model with a fixed output dimension."""

    id = ""
    dimension = 0

    def embed(self, texts):
        raise NotImplementedError


class MiniLmOnnx(EmbeddingModel):
    """sentence-transformers MiniLM on the CPU ONNX runtime (the default)."""

    def __init__(self, model_id, dimension, model_path, tokenizer_path):
        if not model_path or not tokenizer_path:
            raise RuntimeError(
                "tensor::infer requires compiler-provisioned model and tokenizer paths"
            )
        self.id = model_id
        self.dimension = dimension
        self.model_path = model_path
        self.tokenizer_path = tokenizer_path
        self._session = None
        self._tokenizer = None

    def _runtime(self):
        if self._session is None or self._tokenizer is None:
            import onnxruntime as ort
            from tokenizers import Tokenizer

            self._tokenizer = Tokenizer.from_file(self.tokenizer_path)
            self._session = ort.InferenceSession(
                self.model_path,
                providers=["CPUExecutionProvider"],
            )
        return self._session, self._tokenizer

    def embed_one(self, text):
        import numpy as np

        session, tokenizer = self._runtime()
        encoding = tokenizer.encode(text or "")
        ids = encoding.ids[:TENSOR_MAX_TOKENS]
        attention = encoding.attention_mask[:TENSOR_MAX_TOKENS]
        token_types = encoding.type_ids[:TENSOR_MAX_TOKENS]
        if not ids:
            ids = [0]
            attention = [0]
            token_types = [0]

        available = {item.name for item in session.get_inputs()}
        inputs = {}
        if "input_ids" in available:
            inputs["input_ids"] = np.asarray([ids], dtype=np.int64)
        if "attention_mask" in available:
            inputs["attention_mask"] = np.asarray([attention], dtype=np.int64)
        if "token_type_ids" in available:
            inputs["token_type_ids"] = np.asarray([token_types], dtype=np.int64)

        outputs = session.run(None, inputs)
        token_embeddings = np.asarray(outputs[0], dtype=np.float32)
        if token_embeddings.ndim == 3:
            mask = np.asarray(attention, dtype=np.float32)[None, :, None]
            vector = (token_embeddings * mask).sum(axis=1) / np.clip(
                mask.sum(axis=1), 1e-9, None
            )
        elif token_embeddings.ndim == 2:
            vector = token_embeddings
        else:
            raise RuntimeError(
                f"tensor.infer returned unexpected shape {token_embeddings.shape}"
            )
        return _normalize(vector[0], self.dimension, self.id)

    def embed(self, texts):
        return [self.embed_one(text) for text in texts]


class OpenAICompatible(EmbeddingModel):
    """A local or hosted server that speaks `POST {base_url}/embeddings`."""

    def __init__(self, model_id, dimension, base_url, remote_model, api_key=""):
        if not base_url:
            raise RuntimeError(f"embedding model `{model_id}` needs a base URL")
        self.id = model_id
        self.dimension = dimension
        self.base_url = base_url.rstrip("/")
        self.remote_model = remote_model or model_id
        self.api_key = api_key

    def embed(self, texts):
        if not texts:
            return []
        body = json.dumps({"model": self.remote_model, "input": list(texts)}).encode()
        headers = {"content-type": "application/json"}
        if self.api_key:
            headers["authorization"] = f"Bearer {self.api_key}"
        request = urllib.request.Request(
            f"{self.base_url}/embeddings", data=body, headers=headers, method="POST"
        )
        try:
            with urllib.request.urlopen(request, timeout=HTTP_TIMEOUT_SECONDS) as response:
                payload = json.loads(response.read())
        except urllib.error.HTTPError as exc:
            raise RuntimeError(
                f"embedding model `{self.id}` returned HTTP {exc.code} from {self.base_url}"
            ) from exc
        except urllib.error.URLError as exc:
            raise RuntimeError(
                f"embedding model `{self.id}` is unreachable at {self.base_url}: {exc.reason}"
            ) from exc
        data = sorted(payload.get("data") or [], key=lambda item: item.get("index", 0))
        if len(data) != len(texts):
            raise RuntimeError(
                f"embedding model `{self.id}` returned {len(data)} vectors for {len(texts)} texts"
            )
        return [_normalize(item.get("embedding") or [], self.dimension, self.id) for item in data]


def load_model(spec):
    """Build the model named by the compiler's spec (see `embedding_spec_json`)."""
    provider = spec.get("provider")
    model_id = spec["id"]
    dimension = int(spec["dimension"])
    if provider == "onnx-cpu":
        return MiniLmOnnx(
            model_id,
            dimension,
            os.environ.get("SILC_TENSOR_MODEL_PATH", ""),
            os.environ.get("SILC_TENSOR_TOKENIZER_PATH", ""),
        )
    if provider == "openai-compatible":
        base_url = os.environ.get(spec.get("base_url_env") or "", "") or spec.get("base_url") or ""
        key_env = spec.get("api_key_env") or ""
        api_key = os.environ.get(key_env, "") if key_env else ""
        if key_env and not api_key:
            raise RuntimeError(f"embedding model `{model_id}` needs ${key_env} to be set")
        return OpenAICompatible(model_id, dimension, base_url, spec.get("remote_model"), api_key)
    raise RuntimeError(f"unknown embedding provider `{provider}` for `{model_id}`")
